  CONSTRAINT `fk_biz_role_discovery_run_taxonomy_version_id_md_technol_5d5c` FOREIGN KEY (`taxonomy_version_id`) REFERENCES `md_technology_taxonomy_version` (`taxonomy_version_id`)
