INSERT INTO `biz_emerging_role_candidate` (`emerging_role_candidate_id`, `discovery_run_id`, `task_community_id`, `candidate_code`, `proposed_name`, `normalized_name`, `maturity_stage_code`, `workflow_status_code`, `candidate_score`, `nearest_job_role_id`, `overlap_score`, `classification_code`, `mechanical_card_json`, `expression_json`, `expression_model_version`, `risk_flags_json`, `approved_job_role_id`, `created_at`, `updated_at`, `candidate_key`, `support_job_count`, `last_seen_discovery_run_id`) VALUES (1693,74,NULL,'upstream_889d5675cc354507aadb','端到端夹爪控制算法工程师','VLA端到端大模型夹爪','confirmed','approved',1.20,NULL,0.000000,'upstream_signal','{\"caveat\": \"本候选来自上游语料（论文与专利）中已成形、而 JD 中从未出现的技术组合。它是待核查的信号，不是已存在的岗位；参考区间由外部文献先验推出，本系统无法验证，且 U-3 回测不支持「上游领先招聘」这一前提。\", \"source\": \"upstream_corpus\", \"gap_grade\": \"B\", \"jd_mentions\": {\"T1.01.11\": 321, \"T3.04.04\": 4}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"evidence_pairs\": [{\"pair\": [\"T1.01.11\", \"T3.04.04\"], \"grade\": \"B\", \"established_month\": \"2026-08\", \"upstream_cooccurrence\": 5}], \"jd_cooccurrence\": 0, \"technology_codes\": [\"T1.01.11\", \"T3.04.04\"], \"technology_names\": [\"VLA端到端大模型\", \"夹爪\"], \"established_month\": \"2026-08\", \"fact_schema_version\": \"upstream_gap_card_v1\", \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}, \"min_upstream_cooccurrence\": 5}','{\"name\": \"端到端夹爪控制算法工程师\", \"formation_reason\": \"该组合在学术研究中已成形——多篇论文（例如RT‑2、Octo等VLA扩展工作）将视觉‑语言‑动作大模型与夹爪等末端执行器的控制直接结合，验证了端到端抓取的可行性。然而，当前招聘市场上尚未出现专门以VLA端到端驱动夹爪为单一核心职责的岗位，相关能力通常分散在机器人感知、规划或控制的不同职位中，未见显式合并。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"基于VLA端到端大模型，设计并实现夹爪的感知‑决策‑控制一体化算法，使机器人能够根据视觉与语言指令直接输出抓取动作。\", \"core_responsibilities\": [\"利用VLA端到端大模型，构建从视觉与语言输入到夹爪关节指令的端到端映射，并优化模型推理延迟以满足实时控制要求。\", \"针对夹爪的物理特性（如行程、力控、抓取模式），设计适配的模型输出表示与解耦策略，保证动作空间与真实硬件兼容。\", \"在仿真与真实夹爪平台上进行领域随机化训练与Sim2Real迁移，提升模型在未知物体与复杂场景下的抓取成功率。\", \"参与夹爪硬件选型与标定，配合VLA模型输出的动作指令进行闭环调试，分析夹爪运动轨迹与力反馈的异常并迭代模型。\"]}','llm:upstream_gap_naming_v1','[\"no_hiring_evidence\"]',590,'2026-08-26 07:55:58','2026-08-28 15:20:02','upstream_gap|T1.01.11-T3.04.04',0,74),(1694,74,NULL,'upstream_0576ac2ed00345c0b6d6','双臂协同VLA大模型研究员','VLA端到端大模型双臂协同操作','confirmed','approved',1.20,NULL,0.000000,'upstream_signal','{\"caveat\": \"本候选来自上游语料（论文与专利）中已成形、而 JD 中从未出现的技术组合。它是待核查的信号，不是已存在的岗位；参考区间由外部文献先验推出，本系统无法验证，且 U-3 回测不支持「上游领先招聘」这一前提。\", \"source\": \"upstream_corpus\", \"gap_grade\": \"B\", \"jd_mentions\": {\"T1.01.11\": 321, \"T1.09.01\": 2}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"evidence_pairs\": [{\"pair\": [\"T1.01.11\", \"T1.09.01\"], \"grade\": \"B\", \"established_month\": \"2026-08\", \"upstream_cooccurrence\": 5}], \"jd_cooccurrence\": 0, \"technology_codes\": [\"T1.01.11\", \"T1.09.01\"], \"technology_names\": [\"VLA端到端大模型\", \"双臂协同操作\"], \"established_month\": \"2026-08\", \"fact_schema_version\": \"upstream_gap_card_v1\", \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}, \"min_upstream_cooccurrence\": 5}','{\"name\": \"双臂协同VLA大模型研究员\", \"formation_reason\": \"该组合在学术论文与专利中已反复出现，VLA端到端大模型与双臂协同操作在研究侧形成明确的技术收敛，但尚未在招聘市场被单独定义为岗位。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责研发基于VLA端到端大模型的双臂协同操作算法与系统，实现机器人双臂灵巧任务。\", \"core_responsibilities\": [\"设计并训练用于双臂协同操作的VLA端到端大模型，整合视觉、语言与动作模态\", \"优化双臂协同策略，使模型能够在真实或仿真环境中完成抓取、传递、装配等协同任务\", \"构建数据闭环，利用双臂操作数据持续迭代模型性能\", \"与硬件团队协作，将模型部署到双臂机器人平台并进行真机验证\"]}','llm:upstream_gap_naming_v1','[\"no_hiring_evidence\"]',588,'2026-08-26 07:56:27','2026-08-28 15:07:45','upstream_gap|T1.01.11-T1.09.01',0,74),(1695,74,NULL,'upstream_cd3d930de0b34043955f','触觉感知虚实迁移算法工程师','触觉感知算法Sim-to-Real虚实迁移','potential','pending',1.08,NULL,0.000000,'upstream_signal','{\"caveat\": \"本候选来自上游