 \"B\", \"jd_mentions\": {\"T2.02.06\": 1, \"T6.01.06\": 50}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"evidence_pairs\": [{\"pair\": [\"T2.02.06\", \"T6.01.06\"], \"grade\": \"B\", \"established_month\": \"2024-12\", \"upstream_cooccurrence\": 4}], \"jd_cooccurrence\": 0, \"technology_codes\": [\"T2.02.06\", \"T6.01.06\"], \"technology_names\": [\"触觉感知算法\", \"人机交互(通用)\"], \"established_month\": \"2024-12\", \"fact_schema_version\": \"upstream_gap_card_v1\", \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 13.8, \"coefficient\": 1.15, \"high_months\": 27.6, \"technology_classes\": [\"hardware\", \"system_integration\"]}, \"min_upstream_cooccurrence\": 4}','{\"name\": \"触觉人机交互算法研究员\", \"formation_reason\": \"该组合在研究侧已成形：2024年12月的学术论文中，触觉感知算法与人机交互（通用）共同出现的频次达到4次，表明两者在触觉交互、多模态感知等前沿方向已形成固定搭配。然而，招聘市场上尚未出现将两者合一的独立岗位，现有触觉算法工程师多聚焦传感硬件，而交互设计师缺乏算法深度。本说明仅描述这一潜在角色，并不表示市场已存在此类需求。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"研发触觉感知算法，并将其融入人机交互系统，以提升交互的沉浸感与操作直觉。\", \"core_responsibilities\": [\"设计并实现面向人机交互的触觉感知与反馈算法，包括力触觉渲染、纹理识别与交互意图解析。\", \"将触觉感知算法与通用交互框架（如手势、语音、眼动等）集成，构建多模态人机交互原型。\", \"通过用户实验评估触觉交互体验，迭代优化算法参数与交互逻辑。\", \"跟踪学术界触觉感知与人机交互的交叉研究，撰写技术文档及专利。\"]}','llm:upstream_gap_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 08:05:26','2026-08-26 08:05:26','upstream_gap|T2.02.06-T6.01.06',0,74),(1740,79,NULL,'milestone_0845b8a7d2b247d4a6f','灵巧手世界模型架构师','世界模型架构灵巧手(多指)','confirmed','approved',0.63,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"A\", \"milestones\": [{\"event_date\": \"2026-07-05\", \"milestone_code\": \"MS-7c3fcf5655484b749538\", \"milestone_name\": \"Mask2Real-WM分割掩码解耦世界模型发布\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T1.02.10\": 44, \"T3.04.02\": 114}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.02.10\", \"T3.04.02\"], \"technology_names\": [\"世界模型架构\", \"灵巧手(多指)\"], \"established_month\": \"2026-07\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"灵巧手世界模型架构师\", \"formation_reason\": \"灵巧手高自由度操作需要精准预测多指与物体的复杂交互，世界模型架构能够建模环境动态并解耦关键视觉-物理特征。Mask2Real-WM等突破表明分割掩码解耦可有效提升世界模型在真实场景的迁移能力，这一技术路径自然催生出专门将该类世界模型架构应用于灵巧手操控的工作，以解决多指精细操作中长期存在的交互预测与实-虚迁移难题。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责设计面向灵巧手操作的世界模型架构，驱动多指手交互预测与自主操控能力突破。\", \"core_responsibilities\": [\"设计并优化灵巧手操作场景下的世界模型架构，实现分割掩码解耦与高保真物理交互预测\", \"将Mask2Real-WM等分割掩码解耦世界模型适配到灵巧手任务，提升操作序列的生成与评估精度\", \"构建灵巧手交互的世界状态表征，确保模型在多指抓取与精细操作中的时空一致性\", \"参与灵巧手硬件平台的世界模型部署验证，分析模型输出与真实传感数据的偏差并迭代架构\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',591,'2026-08-26 11:45:15','2026-08-28 15:21:30','milestone_gap|T1.02.10-T3.04.02',0,79),(1741,79,NULL,'milestone_5b063c8bbe6b441b986','边缘世界模型部署工程师','世界模型架构算力硬件','confirmed','approved',0.63,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"A\", \"milestones\": [{\"event_date\": \"2026-07-15\", \"milestone_code\": \"MS-917aad10d0da45789999\", \"milestone_name\": \"NVIDIA Cosmos 3 Edge发布\", \"milestone_type_code\": \"product_release\"}], \"jd_mentions\": {\"T1.02.10\": 44, \"T3.08.04\": 108}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.02.10\", \"T3.08.04\"], \"technology_names\": [\"世界模型架构\", \"算力硬件\"], \"established_month\": \"2026-07\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"边缘世界模型部署工程师\", \"formation_reason\": \"世界模型架构需要大量并行计算与高带宽存储，而边缘算力硬件天然受功耗、面积与实时性制约。直接将云端世界模型下沉到边缘会因算力失配而无法运行，因此必须由同时理解世界模型内部计算图与底层硬件流水线的人来设计协同优化方案，这类工作无法由分开的模型设计与硬件调优两个岗位简单拼接完成。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责将世界模型架构高效适配并部署到边缘算力硬件，实现端侧实时推理与自治决策。\", \"core_responsibilities\": [\"分析边缘算力硬件（如 NVIDIA Cosmos 3 Edge）的并行计算、存储与带宽特性，制定世界模型在端侧部署的算力分配方案\", \"根据边缘硬件约束，剪裁、量化或重构世界模型架构，平衡模型精度与推理延迟\", \"实现世界模型在边缘设备上的高性能推理，优化算子调度与内存管理\", \"搭建硬件在环测试环境，验证世界模型在真实边缘场景下的实时性与可靠性\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',589,'2026-08-26 11:45:28','2026-08-28 15:07:49','milestone_gap|T1.02.10-T3.08.04',0,79),(1742,79,NULL,'milestone_447d637de8ea42eda4d','具身端到端模型研发专家','VLA端到端大模型具身感知与交互','potential','pending',0.44,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-07-05\", \"milestone_code\": \"MS-a931a408e9a647b38904\", \"milestone_name\": \"ACE-Brain-0.5 8B统一具身基础模型发布\", \"milestone_type_code\": \"product_release\"}], \"jd_mentions\": {\"T1.01.11\": 321, \"T2.02.08\": 1}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.01.11\", \"T2.02.08\"], \"technology_names\": [\"VLA端到端大模型\", \"具身感知与交互\"], \"established_month\": \"2026-07\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"具身端到端模型研发专家\", \"formation_reason\": \"VLA端到端大模型将感知、规划和动作统一为单一模型，而具身感知与交互是其最直接的应用出口。在机器人需要理解环境并实时生成物理动作的闭环系统中，这两种能力必然耦合：端到端模型需要从具身感知中获得输入并输出可执行的交互动作，而具身交互的反馈又反过来驱动模型优化。这一循环形成了“模型训练-感知交互-真机验证”的完整工作流，从而催生了一类需要同时掌握VLA端到端建模与具身交互系统开发的研发岗位。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"基于VLA端到端大模型，负责具身感知与交互能力的模型研发与系统集成，推动机器人在真实环境中的端到端感知-动作闭环。\", \"core_responsibilities\": [\"设计并训练VLA端到端大模型，融合视觉、语言与动作模态，实现机器人自主感知-决策-执行闭环。\", \"开发具身感知与交互模块，包括多模态环境理解、人机交互意图识别及物理动作生成。\", \"在真机场景下部署和优化VLA模型，解决感知噪声、动作延迟等具身落地问题。\", \"构建数据采集与闭环反馈机制，迭代提升模型在复杂场景中的泛化能力和交互自然度。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:45:44','2026-08-26 11:45:44','milestone_gap|T1.01.11-T2.02.08',0,79),(1743,79,NULL,'milestone_d78eacb2d7f44570a2b','世界模型芯片适配工程师','世界模型架构AI芯片','potential','pending',0.44,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-07-07\", \"milestone_code\": \"MS-6b162fb03c3c42c6b166\", \"milestone_name\": \"MoWorld全球首个50+FPS世界模型发布\", \"milestone_type_code\": \"product_release\"}], \"jd_mentions\": {\"T1.02.10\": 44, \"T3.08.01\": 62}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.02.10\", \"T3.08.01\"], \"technology_names\": [\"世界模型架构\", \"AI芯片\"], \"established_month\": \"2026-07\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"世界模型芯片适配工程师\", \"formation_reason\": \"世界模型架构需要在高帧率下维持对复杂环境的实时推演，通用计算平台难以满足其严苛的延迟与能效要求。AI芯片作为专用加速硬件，恰好能提供所需的算力密度，但世界模型的计算图、稀疏激活和注意力模式与常见深度学习模型差异显著，不经适配无法发挥芯片潜力。因此，同时掌握世界模型架构理解与AI芯片底层实现能力，成为将这类前沿模型从实验室推向实时应用的关键缺口，催生了专注于跨层优化的集成性工作。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责将世界模型架构高效部署到AI芯片上，实现实时交互性能的优化与落地。\", \"core_responsibilities\": [\"分析世界模型架构的计算特性，设计其在AI芯片上的算子映射与并行策略\", \"针对AI芯片的存储层级与计算单元，优化世界模型推理的延迟与吞吐量\", \"协同硬件团队，根据世界模型负载特征提出AI芯片架构的改进建议\", \"解决世界模型在AI芯片上部署时的精度损失与运行时稳定性问题\", \"构建从世界模型框架到AI芯片的端到端编译与部署工具链\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:45:58','2026-08-26 11:45:58','milestone_gap|T1.02.10-T3.08.01',0,79),(1744,79,NULL,'milestone_d54211df276147c0894','数字孪生三维重建工程师','3D重建数字孪生','potential','pending',0.42,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-06-09\", \"milestone_code\": \"MS-fd1fd69a941249a194d5\", \"milestone_name\": \"ManiSplat图形结构解耦3DGS架构发布\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T2.05.03\": 44, \"T4.03.03\": 6}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T2.05.03\", \"T4.03.03\"], \"technology_names\": [\"3D重建\", \"数字孪生\"], \"established_month\": \"2026-06\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"数字孪生三维重建工程师\", \"formation_reason\": \"3D重建提供从现实世界获取几何与外观信息的能力，数字孪生则依赖这种信息构建高保真虚拟镜像。当以ManiSplat为代表的图形结构解耦3DGS架构取得突破，重建效率与可编辑性大幅提升，使得需要专人负责将重建技术系统性地嵌入数字孪生工作流，从而形成聚焦于“重建即孪生”的专业岗位。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责利用3D重建技术构建和维护高保真数字孪生模型，支撑虚实映射与仿真分析。\", \"core_responsibilities\": [\"基于多源数据执行3D重建任务，生成面向数字孪生的几何与纹理模型\", \"设计和优化数字孪生场景中的三维重建管线，确保模型精度与实时性\", \"将重建成果集成到数字孪生平台中，实现物理实体到虚拟空间的动态映射\", \"跟踪如ManiSplat等新型3DGS架构进展，评估其在数字孪生重建中的应用潜力\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:46:11','2026-08-26 11:46:11','milestone_gap|T2.05.03-T4.03.03',0,79),(1745,79,NULL,'milestone_03c01076b55a4222a70','世界模型数据集ROS开发工程师','世界模型数据集ROS','potential','pending',0.42,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-06-22\", \"milestone_code\": \"MS-fb1ec321be3c438dad22\", \"milestone_name\": \"如祺出行发布具身智能数据平台\", \"milestone_type_code\": \"platform_release\"}], \"jd_mentions\": {\"T1.02.08\": 4, \"T5.01.01\": 301}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.02.08\", \"T5.01.01\"], \"technology_names\": [\"世界模型数据集\", \"ROS\"], \"established_month\": \"2026-06\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 9.0, \"coefficient\": 0.9, \"high_months\": 16.2, \"technology_classes\": [\"algorithm\", \"system_integration\"]}}','{\"name\": \"世界模型数据集ROS开发工程师\", \"formation_reason\": \"世界模型需要大量真实或仿真交互数据，ROS作为机器人领域通用的分布式通信框架，自然成为采集、传输和处理这些数据的核心基础设施。将世界模型数据集的生产与ROS深度绑定，需要既懂ROS系统开发又熟悉数据集工程的专业人员，以打通从机器人传感器到模型训练集的完整链路，因此形成了这一综合能力需求。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责在ROS环境下构建与维护面向世界模型训练的数据集处理管线。\", \"core_responsibilities\": [\"基于ROS开发数据采集节点，实现多传感器数据的同步与记录\", \"设计并维护世界模型数据集的组织结构、标注规范与版本管理\", \"搭建数据预处理、清洗与增强的ROS工具链，确保数据质量\", \"协同算法团队，将数据集高效接入世界模型训练与评估流程\", \"监控数据管道运行状态，处理ROS节点异常并优化数据吞吐\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:46:49','2026-08-26 11:46:49','milestone_gap|T1.02.08-T5.01.01',0,79),(1746,79,NULL,'milestone_3cc3fd3bf1774b16be6','精密运动部件视觉检测工程师','机器视觉谐波减速器','confirmed','approved',0.42,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-06-22\", \"milestone_code\": \"MS-6b7e43948e88452ab0aa\", \"milestone_name\": \"特斯拉Optimus Gen3供应链首次披露\", \"milestone_type_code\": \"other\"}], \"jd_mentions\": {\"T2.02.07\": 49, \"T3.06.01\": 25}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T2.02.07\", \"T3.06.01\"], \"technology_names\": [\"机器视觉\", \"谐波减速器\"], \"established_month\": \"2026-06\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 19.5, \"coefficient\": 1.3, \"high_months\": 31.2, \"technology_classes\": [\"hardware\"]}}','{\"name\": \"精密运动部件视觉检测工程师\", \"formation_reason\": \"在特斯拉Optimus Gen3供应链披露中，谐波减速器作为核心关节模组的关键部件被正式纳入，其量产一致性高度依赖微观缺陷的在线筛除。机器视觉恰好能够提供非接触、高节拍的检测手段，但该能力组合尚未在招聘市场上形成独立岗位，更多由机器人厂商与自动化集成商在产线落地时，将视觉工程与精密传动工艺临时耦合，反映出精密传动部件从抽检向全检迁移过程中，对跨领域复合能力的阶段性需求。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"利用机器视觉方法对谐波减速器等精密传动部件进行缺陷识别与质量判定，确保运动执行部件的装配品质与可靠性。\", \"core_responsibilities\": [\"搭建并优化针对谐波减速器关键零件（如柔轮、刚轮、波发生器）的视觉检测系统，实现表面缺陷、尺寸偏差的自动识别与分类。\", \"制定与迭代视觉检测方案，包括光源、镜头、相机选型及算法参数调优，提升对微小形变与加工纹理的区分能力。\", \"对接生产节拍，将视觉检测工站嵌入谐波减速器装配线，处理检测数据的实时反馈与NG品分流逻辑。\", \"编制检测工艺标准与操作规范，协同工艺与质量部门分析典型失效模式，驱动制程改进。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',592,'2026-08-26 11:46:59','2026-08-28 15:21:33','milestone_gap|T2.02.07-T3.06.01',0,79),(1747,79,NULL,'milestone_3921d0d7e87841ad8a4','ECoT具身推理研发专家','具身推理机制具身推理与ECoT','potential','pending',0.42,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-06-30\", \"milestone_code\": \"MS-8ad6a5b980f74d31ad5d\", \"milestone_name\": \"ZR-0 ECoT VLA开源\", \"milestone_type_code\": \"open_source\"}], \"jd_mentions\": {\"T1.01.05\": 11, \"T1.07.01\": 1}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.01.05\", \"T1.07.01\"], \"technology_names\": [\"具身推理机制\", \"具身推理与ECoT\"], \"established_month\": \"2026-06\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"ECoT具身推理研发专家\", \"formation_reason\": \"具身智能体在长周期、多步骤任务中需要可解释的推理能力，而传统端到端模型缺乏中间推理步骤，导致决策僵硬且难以纠错。随着具身链式思维（ECoT）的提出，将自然语言推理模式引入物理世界成为可能，ZR-0 ECoT VLA的开源则为这一方向提供了可复现的技术基线。要真正在机器人上实现ECoT推理机制，需要同时掌握具身推理框架设计与ECoT方法论的人才，将推理过程从抽象算法转化为实体可执行的闭环系统，因此自然催生了围绕这一能力组合的工作内容。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责具身智能体中推理机制与具身链式思维（ECoT）的设计、实现与优化，推动复杂任务下的自主决策能力。\", \"core_responsibilities\": [\"设计并实现适用于具身智能体的推理机制，包括状态感知、目标分解与动作规划的逻辑框架。\", \"将具身链式思维（ECoT）方法融入视觉-语言-动作（VLA）模型，构建可解释的推理链路。\", \"基于ZR-0 ECoT等开源框架，针对实际机器人平台进行推理模块的适配、微调与性能优化。\", \"协同感知、规划与控制团队，确保推理输出与底层执行闭环的可靠衔接。\", \"跟踪具身推理与ECoT的最新研究进展，将前沿技术转化为可落地的工程方案。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:47:23','2026-08-26 11:47:23','milestone_gap|T1.01.05-T1.07.01',0,79),(1748,79,NULL,'milestone_9cd9822edc8242e0b2b','灵巧手操作仿真数据工程师','灵巧手(多指)合成数据','potential','pending',0.40,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-05-18\", \"milestone_code\": \"MS-81ce2604f5f240de8f8d\", \"milestone_name\": \"Dexora发布全球首个开源双臂36-DoF灵巧VLA\", \"milestone_type_code\": \"open_source\"}], \"jd_mentions\": {\"T3.04.02\": 114, \"T4.02.01\": 13}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T3.04.02\", \"T4.02.01\"], \"technology_names\": [\"灵巧手(多指)\", \"合成数据\"], \"established_month\": \"2026-05\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"灵巧手操作仿真数据工程师\", \"formation_reason\": \"灵巧手的高自由度操作需要海量且多样化的训练样本，真实采集成本极高且难以覆盖长尾场景。合成数据能够以可控、可扩展的方式生成带标注的操作数据，同时灵巧手仿真平台的发展使得合成经验与真实迁移成为可能，因而自然催生出将灵巧手操作知识与合成数据生成能力结合的工作方向，专注于为灵巧手技能学习构建高质量的数据基础。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责为多指灵巧手操作任务构建合成数据生成流水线，支撑机器人操作技能的学习与泛化。\", \"core_responsibilities\": [\"设计并实现面向多指灵巧手操作的合成数据生成方案，覆盖抓取、灵巧操作等多样化任务场景\", \"搭建与维护灵巧手仿真环境，确保物理交互的真实性与传感器数据的逼真度\", \"生成大规模、带标注的灵巧手操作数据，包含视觉、触觉与关节状态等多模态信息\", \"评估合成数据在灵巧手策略训练中的有效性，迭代优化数据分布与生成策略\", \"与灵巧手硬件团队和算法团队协作，将合成数据用于真实灵巧手模型的迁移与验证\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:47:39','2026-08-26 11:47:39','milestone_gap|T3.04.02-T4.02.01',0,79),(1749,79,NULL,'milestone_9146f028db3543058bd','焊接机器人世界模型架构师','世界模型架构焊接机器人','potential','pending',0.38,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-04-30\", \"milestone_code\": \"MS-53097864c8724d5daaf7\", \"milestone_name\": \"小雨智造发布业内首款具身智能焊接机器人, 起售价16.98万元\", \"milestone_type_code\": \"product_release\"}], \"jd_mentions\": {\"T1.02.10\": 44, \"T7.01.03\": 1}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.02.10\", \"T7.01.03\"], \"technology_names\": [\"世界模型架构\", \"焊接机器人\"], \"established_month\": \"2026-04\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 9.0, \"coefficient\": 0.9, \"high_months\": 16.2, \"technology_classes\": [\"algorithm\", \"system_integration\"]}}','{\"name\": \"焊接机器人世界模型架构师\", \"formation_reason\": \"焊接机器人从传统示教向自主作业演进，必须在非结构化环境中理解工件形态、焊缝位置与实时变化，世界模型架构正是实现这一理解的核心技术。该能力组合对应一类工作，即系统性地为焊接机器人设计、实现和维护世界模型，使其具备空间推理和工艺自适应能力，从而支撑产品化落地。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"主导焊接机器人基于世界模型的空间感知、运动规划与工艺自适应架构的设计与实现。\", \"core_responsibilities\": [\"设计面向焊接场景的世界模型表达框架，包括工件几何重建、焊缝跟踪与熔池动态建模\", \"构建支持多模态传感融合的世界模型更新机制，实现实时环境感知与状态预测\", \"定义世界模型与机器人运动规划、焊接工艺参数控制的接口，保障决策-执行闭环\", \"制定世界模型在焊接机器人嵌入式系统上的部署方案与性能优化策略\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:47:55','2026-08-26 11:47:55','milestone_gap|T1.02.10-T7.01.03',0,79),(1750,79,NULL,'milestone_97d1ad0df2c8414e949','仿真域随机化系统工程师','高保真仿真(3DGS)域随机化','potential','pending',0.33,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-01-01\", \"milestone_code\": \"MS-a52c05d2359b4e30b83d\", \"milestone_name\": \"ViserDex在3DGS空间执行域随机化\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T4.03.01\": 33, \"T4.04.01\": 4}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T4.03.01\", \"T4.04.01\"], \"technology_names\": [\"高保真仿真(3DGS)\", \"域随机化\"], \"established_month\": \"2026-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"仿真域随机化系统工程师\", \"formation_reason\": \"高保真仿真（3DGS）能够提供视觉逼真、可微分的环境，但仅靠仿真难以消除sim-to-real差距；域随机化则通过主动扰动仿真参数来覆盖真实世界的多样性。两者结合才能形成完整的仿真到现实迁移方案，ViserDex在3DGS空间执行域随机化即体现了这一技术闭环。在产业实践中，需要有人同时掌握3DGS仿真构建与域随机化策略设计，才能端到端地负责从仿真环境搭建到泛化策略验证的工程链路，因此逐渐形成一类专精于该组合的工作角色。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责基于3DGS高保真仿真环境，设计并实施域随机化策略，以提升具身智能模型在真实场景中的泛化能力。\", \"core_responsibilities\": [\"基于3DGS技术构建高保真仿真场景，确保视觉与物理属性的逼真度\", \"针对特定任务设计域随机化方案，覆盖视觉、动力学、光照等多维度参数扰动\", \"将域随机化流程集成到仿真训练管线中，实现自动化随机化数据生成\", \"分析域随机化对模型性能的影响，迭代优化随机化分布与参数范围\", \"与算法团队协作，将仿真训练的策略无缝迁移至真实机器人平台\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:48:09','2026-08-26 11:48:09','milestone_gap|T4.03.01-T4.04.01',0,79),(1751,79,NULL,'milestone_b4650f2eec4042af965','多目标全身控制算法工程师','全身控制(WBC)多目标跟踪','potential','pending',0.33,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2026-01-01\", \"milestone_code\": \"MS-5860e250c7764179be71\", \"milestone_name\": \"HWC-Loco层次化鲁棒WBC发布\", \"milestone_type_code\": \"paper\"}], \"jd_mentions\": {\"T1.03.01\": 33, \"T1.06.11\": 11}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.03.01\", \"T1.06.11\"], \"technology_names\": [\"全身控制(WBC)\", \"多目标跟踪\"], \"established_month\": \"2026-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"多目标全身控制算法工程师\", \"formation_reason\": \"在具身智能向服务、协作等动态场景演进时，机器人必须同时具备对多个移动目标的感知能力与全身协调控制能力。HWC-Loco等层次化鲁棒WBC工作已展示将该两种技术结合的研究路径，但工程化落地要求将多目标跟踪的异步、不确定输出直接纳入全身控制回路，形成一类需要同时精通感知与运动控制的交叉问题，从而催生了此类融合性岗位的工作内容，只是招聘市场尚未将其独立为正式职位。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"融合多目标跟踪与全身控制技术，实现机器人在动态多目标环境中的实时运动规划与安全交互。\", \"core_responsibilities\": [\"开发并优化多目标跟踪算法，实时估计环境中多个动态目标的位置、运动状态与意图。\", \"设计并实现全身控制器（WBC），将多目标感知信息作为约束或目标，生成机器人全身运动轨迹与力矩指令。\", \"构建感知-控制闭环框架，解决感知延迟、噪声下的鲁棒全身运动规划，保障机器人在人群或动态对象中的安全与任务执行。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:48:41','2026-08-26 11:48:41','milestone_gap|T1.03.01-T1.06.11',0,79),(1752,79,NULL,'milestone_2bcc97fba6ca4d9ea5f','具身仿真运动规划工程师','运动规划高保真仿真(3DGS)','potential','pending',0.18,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2025-01-01\", \"milestone_code\": \"MS-b342e36b71574b649d2a\", \"milestone_name\": \"3DGS数字孪生+MoveIt闭环发布\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T1.03.04\": 26, \"T4.03.01\": 33}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.03.04\", \"T4.03.01\"], \"technology_names\": [\"运动规划\", \"高保真仿真(3DGS)\"], \"established_month\": \"2025-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"具身仿真运动规划工程师\", \"formation_reason\": \"3DGS提供快速、高真实感的场景重建能力，使数字孪生能够以较低成本覆盖多样化的操作环境；运动规划器像MoveIt在闭环中需要反复与环境交互来验证避障、抓取等行为的可靠性。两者结合可以形成‘仿真内闭环验证’的工作流，专门解决机器人运动规划在真实场景部署前的大规模、高保真测试问题，这是机器人产品化过程中一个自然分化的工程环节。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"基于3DGS高保真数字孪生环境，开发和验证机器人闭环运动规划算法，提升仿真到现实的一致性。\", \"core_responsibilities\": [\"构建和维护基于3DGS的高保真仿真环境，用于机器人运动规划算法的闭环测试与迭代\", \"将运动规划模块（如MoveIt）与3DGS数字孪生系统集成，实现感知-规划-执行的全链路仿真\", \"设计并执行仿真实验，分析运动规划在真实感场景下的性能瓶颈，并优化算法鲁棒性\", \"开发仿真环境与真实机器人之间的标定与迁移工具，减小sim-to-real差距\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:48:51','2026-08-26 11:48:51','milestone_gap|T1.03.04-T4.03.01',0,79),(1753,79,NULL,'milestone_4dde1c2d27f44a8eb6c','数字孪生运动规划系统工程师','运动规划数字孪生','potential','pending',0.18,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2025-01-01\", \"milestone_code\": \"MS-b342e36b71574b649d2a\", \"milestone_name\": \"3DGS数字孪生+MoveIt闭环发布\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T1.03.04\": 26, \"T4.03.03\": 6}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.03.04\", \"T4.03.03\"], \"technology_names\": [\"运动规划\", \"数字孪生\"], \"established_month\": \"2025-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"数字孪生运动规划系统工程师\", \"formation_reason\": \"数字孪生为运动规划提供了可重复、高保真的验证环境，而运动规划的性能又依赖于数字孪生的精度与反馈速度，两者在闭环迭代中紧密耦合，催生了对同时掌握数字孪生构建与运动规划集成能力的工程需求。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责构建高保真数字孪生环境，并将运动规划算法集成于其中，实现闭环验证与迭代优化。\", \"core_responsibilities\": [\"搭建和维护面向机器人系统的数字孪生场景，模拟真实工作环境与物理交互。\", \"将运动规划模块部署至数字孪生平台，执行闭环仿真测试并评估路径规划的实时性与安全性。\", \"基于数字孪生的反馈数据，调整运动规划参数与策略，提升从仿真到现实迁移的可靠性。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:49:18','2026-08-26 11:49:18','milestone_gap|T1.03.04-T4.03.03',0,79),(1754,79,NULL,'milestone_d3fcc60fe6264c12983','灵巧操作策略算法工程师','扩散策略灵巧操作','potential','pending',0.06,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2023-01-01\", \"milestone_code\": \"MS-5597c6881ea64fa1b29c\", \"milestone_name\": \"Diffusion Policy发布：扩散策略革命开启\", \"milestone_type_code\": \"paper\"}], \"jd_mentions\": {\"T1.05.01\": 3, \"T1.09.05\": 17}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.05.01\", \"T1.09.05\"], \"technology_names\": [\"扩散策略\", \"灵巧操作\"], \"established_month\": \"2023-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"灵巧操作策略算法工程师\", \"formation_reason\": \"扩散策略的发布为机器人动作生成提供了新的生成式模型范式，尤其适合灵巧操作这种高维、多模态的动作空间。该技术组合在产业侧已通过论文里程碑出现，但尚未形成明确岗位，原因是灵巧操作本身仍处于前沿探索阶段，将扩散策略工程化落地需要专门的角色来连接算法研究与实际系统集成，从而催生了这类聚焦扩散策略与灵巧操作结合的研究型工程师工作。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责将扩散策略应用于灵巧操作任务，实现从感知到动作生成的端到端算法研发与优化。\", \"core_responsibilities\": [\"研究扩散策略在灵巧操作场景下的行为克隆与动作生成方法\", \"设计并实现适用于灵巧手的高维动作空间扩散模型训练与推理流程\", \"搭建仿真环境，收集专家演示数据，验证扩散策略在灵巧操作任务中的成功率与泛化能力\", \"优化扩散策略的实时性，使其能够部署在真机灵巧手系统上\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:49:32','2026-08-26 11:49:32','milestone_gap|T1.05.01-T1.09.05',0,79),(1755,79,NULL,'milestone_eb8c82855892480ab67','四足机器人策略蒸馏算法工程师','四足机器人策略蒸馏','potential','pending',0.01,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2020-01-01\", \"milestone_code\": \"MS-bb665f088b48428fbf69\", \"milestone_name\": \"教师-学生蒸馏在ANYmal上系统化\", \"milestone_type_code\": \"breakthrough\"}], \"jd_mentions\": {\"T3.02.01\": 157, \"T4.04.03\": 1}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T3.02.01\", \"T4.04.03\"], \"technology_names\": [\"四足机器人\", \"策略蒸馏\"], \"established_month\": \"2020-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 10.5, \"coefficient\": 1.05, \"high_months\": 25.2, \"technology_classes\": [\"algorithm\", \"hardware\"]}}','{\"name\": \"四足机器人策略蒸馏算法工程师\", \"formation_reason\": \"四足机器人通常依赖深度强化学习策略实现复杂运动，但高性能策略往往体量庞大，难以在机器人端侧实时运行。策略蒸馏能将知识从大模型（教师）迁移到轻量模型（学生），在保持控制效果的同时大幅降低计算开销。ANYmal平台已系统化验证了该技术路径的可行性，表明该组合能够系统性地解决四足机器人策略部署的工程瓶颈，因此逐步形成一类专门负责策略蒸馏与四足机器人结合的工作方向。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责四足机器人运动控制策略的蒸馏优化，将复杂教师策略压缩为高效学生策略，并部署至真实机器人平台。\", \"core_responsibilities\": [\"设计并实现面向四足机器人的教师-学生策略蒸馏框架，提升策略在有限算力下的实时性\", \"在仿真环境中训练四足机器人运动控制教师策略，完成策略蒸馏实验与性能评估\", \"解决策略蒸馏过程中的sim-to-real差距，将蒸馏后的学生策略部署到实际四足机器人上\", \"优化蒸馏算法，平衡策略精度、推理速度与鲁棒性，满足四足机器人高动态运动需求\", \"维护策略蒸馏工具链，与机器人硬件团队协作完成整机集成与测试\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:50:16','2026-08-26 11:50:16','milestone_gap|T3.02.01-T4.04.03',0,79),(1756,79,NULL,'milestone_efa68bb0c26a4aa082d','灵巧操作仿真迁移工程师','灵巧操作域随机化','potential','pending',0.00,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2018-07-01\", \"milestone_code\": \"MS-ee44cca4479a4d8bb67c\", \"milestone_name\": \"OpenAI Dactyl单手解魔方\", \"milestone_type_code\": \"paper\"}], \"jd_mentions\": {\"T1.09.05\": 17, \"T4.04.01\": 4}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T1.09.05\", \"T4.04.01\"], \"technology_names\": [\"灵巧操作\", \"域随机化\"], \"established_month\": \"2018-07\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 8.0, \"coefficient\": 0.8, \"high_months\": 12.0, \"technology_classes\": [\"algorithm\"]}}','{\"name\": \"灵巧操作仿真迁移工程师\", \"formation_reason\": \"灵巧操作任务需要大量试错，直接在真实机器人上采集训练数据成本极高且存在安全风险，而域随机化技术通过在仿真中引入大量随机变化，使策略学会忽略无关差异，从而无需真实数据即可实现从仿真到现实的泛化。OpenAI Dactyl 的成功表明，两者的结合能够解决高难度手部操作任务，因此自然形成了一类专注于利用域随机化实现灵巧操作策略迁移的工作，这类工作虽未在招聘市场上被独立成岗，但在前沿研究中已具备明确的职责边界。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"负责基于域随机化技术，在仿真环境中训练灵巧操作策略并实现向真实机器人的零样本或小样本迁移，攻克高自由度手部操作任务。\", \"core_responsibilities\": [\"构建灵巧操作任务的仿真环境，设计涵盖多样化物理参数、视觉纹理和动力学特性的随机化域\", \"研发适用于灵巧操作策略的域随机化算法，缩小仿真与现实之间的分布差距\", \"训练并优化灵巧操作策略（如单手解魔方等），使其在随机化域中具备鲁棒性\", \"将仿真训练的策略部署到真实机器人手上，进行迁移验证与性能调优\", \"分析仿真到现实迁移的效果，迭代域随机化方案与策略网络架构\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:50:36','2026-08-26 11:50:36','milestone_gap|T1.09.05-T4.04.01',0,79),(1757,79,NULL,'milestone_e3be6574c9dc436db6e','具身智能仿真测试认证工程师','域随机化检测认证','potential','pending',0.00,NULL,0.000000,'milestone_signal','{\"caveat\": \"本候选的依据是具身智能领域里程碑事件中已共现、而全部 JD 中从未共现的技术组合。里程碑说明该组合在产业侧已经出现过，并不说明有人在为它招聘；它是待核查的信号，不是已存在的岗位。参考区间由外部文献先验推出，本系统无法验证。\", \"source\": \"milestone_events\", \"gap_grade\": \"B\", \"milestones\": [{\"event_date\": \"2017-01-01\", \"milestone_code\": \"MS-f8e5d8ae04244b4895d6\", \"milestone_name\": \"域随机化(DR)概念提出并在OpenAI Dactyl中系统应用\", \"milestone_type_code\": \"paper\"}], \"jd_mentions\": {\"T4.04.01\": 4, \"T6.03.04\": 203}, \"llm_boundary\": \"expression_only_no_fact_mutation\", \"jd_cooccurrence\": 0, \"milestone_count\": 1, \"technology_codes\": [\"T4.04.01\", \"T6.03.04\"], \"technology_names\": [\"域随机化\", \"检测认证\"], \"established_month\": \"2017-01\", \"fact_schema_version\": \"milestone_gap_card_v1\", \"verified_milestone_count\": 1, \"expected_transmission_lag\": {\"status\": \"reference_prior\", \"low_months\": 9.0, \"coefficient\": 0.9, \"high_months\": 16.2, \"technology_classes\": [\"algorithm\", \"system_integration\"]}}','{\"name\": \"具身智能仿真测试认证工程师\", \"formation_reason\": \"域随机化技术能够系统性地生成大量仿真变体，恰好弥补传统检测认证中真实测试场景覆盖不足的问题。当具身智能产品需要证明其在广泛真实条件下仍能可靠工作时，自然需要将域随机化作为测试生成手段嵌入检测认证流程，从而催生出专门负责将这两者结合的角色。\", \"generation_method\": \"llm_expression\", \"one_line_definition\": \"利用域随机化构建高覆盖度仿真测试环境，对具身智能系统进行检测与认证，确保其真实世界部署的鲁棒性。\", \"core_responsibilities\": [\"设计并实施域随机化策略，生成多样化的仿真测试场景，覆盖视觉、动力学、光照等关键差异维度。\", \"根据检测认证标准，制定基于域随机化的测试方案，评估具身智能系统在未见过环境中的性能表现。\", \"分析域随机化测试结果，识别系统失稳边界，并向算法团队反馈改进方向，支撑认证通过判定。\", \"维护和完善域随机化工具链，确保测试流程可复现、可追溯，符合检测认证体系要求。\"]}','llm:milestone_combination_naming_v1','[\"no_hiring_evidence\"]',NULL,'2026-08-26 11:50:49','2026-08-26 11:50:49','milestone_gap|T4.04.01-T6.03.04',0,79);
