INSERT INTO `biz_standard_job_description` (`standard_jd_id`, `standard_jd_code`, `emerging_role_candidate_id`, `job_role_version_id`, `version_no`, `title_text`, `content_json`, `generation_method_code`, `model_version`, `is_market_evidence`, `approval_status_code`, `created_at`, `data_origin_code`) VALUES (2,'SJD-6BAF2CAB95924824',1694,753,1,'双臂协同VLA大模型研究员','{\"title\": \"双臂协同VLA大模型研究员\", \"definition\": \"负责研发基于VLA端到端大模型的双臂协同操作算法与系统，实现机器人双臂灵巧任务。\", \"disclaimer\": \"参考模板，不代表真实招聘，不计入市场热度与岗位证据。\", \"responsibilities\": [\"设计并训练用于双臂协同操作的VLA端到端大模型，整合视觉、语言与动作模态\", \"优化双臂协同策略，使模型能够在真实或仿真环境中完成抓取、传递、装配等协同任务\", \"构建数据闭环，利用双臂操作数据持续迭代模型性能\", \"与硬件团队协作，将模型部署到双臂机器人平台并进行真机验证\"], \"technology_node_ids\": [4577, 4644]}','mechanical',NULL,0,'approved','2026-08-28 15:07:45','algorithm_inference'),(3,'SJD-1FAAF2A5AD144811',1741,754,1,'边缘世界模型部署工程师','{\"title\": \"边缘世界模型部署工程师\", \"definition\": \"负责将世界模型架构高效适配并部署到边缘算力硬件，实现端侧实时推理与自治决策。\", \"disclaimer\": \"参考模板，不代表真实招聘，不计入市场热度与岗位证据。\", \"responsibilities\": [\"分析边缘算力硬件（如 NVIDIA Cosmos 3 Edge）的并行计算、存储与带宽特性，制定世界模型在端侧部署的算力分配方案\", \"根据边缘硬件约束，剪裁、量化或重构世界模型架构，平衡模型精度与推理延迟\", \"实现世界模型在边缘设备上的高性能推理，优化算子调度与内存管理\", \"搭建硬件在环测试环境，验证世界模型在真实边缘场景下的实时性与可靠性\"], \"technology_node_ids\": [4588, 4713]}','mechanical',NULL,0,'approved','2026-08-28 15:07:49','algorithm_inference'),(4,'SJD-E8E6C111297A4D2E',1693,755,1,'端到端夹爪控制算法工程师','{\"title\": \"端到端夹爪控制算法工程师\", \"definition\": \"基于VLA端到端大模型，设计并实现夹爪的感知‑决策‑控制一体化算法，使机器人能够根据视觉与语言指令直接输出抓取动作。\", \"disclaimer\": \"参考模板，不代表真实招聘，不计入市场热度与岗位证据。\", \"responsibilities\": [\"利用VLA端到端大模型，构建从视觉与语言输入到夹爪关节指令的端到端映射，并优化模型推理延迟以满足实时控制要求。\", \"针对夹爪的物理特性（如行程、力控、抓取模式），设计适配的模型输出表示与解耦策略，保证动作空间与真实硬件兼容。\", \"在仿真与真实夹爪平台上进行领域随机化训练与Sim2Real迁移，提升模型在未知物体与复杂场景下的抓取成功率。\", \"参与夹爪硬件选型与标定，配合VLA模型输出的动作指令进行闭环调试，分析夹爪运动轨迹与力反馈的异常并迭代模型。\"], \"technology_node_ids\": [4577, 4698]}','mechanical',NULL,0,'approved','2026-08-28 15:20:02','algorithm_inference'),(5,'SJD-AD1F89340EEA41D1',1740,756,1,'灵巧手世界模型架构师','{\"title\": \"灵巧手世界模型架构师\", \"definition\": \"负责设计面向灵巧手操作的世界模型架构，驱动多指手交互预测与自主操控能力突破。\", \"disclaimer\": \"参考模板，不代表真实招聘，不计入市场热度与岗位证据。\", \"responsibilities\": [\"设计并优化灵巧手操作场景下的世界模型架构，实现分割掩码解耦与高保真物理交互预测\", \"将Mask2Real-WM等分割掩码解耦世界模型适配到灵巧手任务，提升操作序列的生成与评估精度\", \"构建灵巧手交互的世界状态表征，确保模型在多指抓取与精细操作中的时空一致性\", \"参与灵巧手硬件平台的世界模型部署验证，分析模型输出与真实传感数据的偏差并迭代架构\"], \"technology_node_ids\": [4588, 4696]}','mechanical',NULL,0,'approved','2026-08-28 15:21:30','algorithm_inference'),(6,'SJD-D10678D18BF348F0',1746,757,1,'精密运动部件视觉检测工程师','{\"title\": \"精密运动部件视觉检测工程师\", \"definition\": \"利用机器视觉方法对谐波减速器等精密传动部件进行缺陷识别与质量判定，确保运动执行部件的装配品质与可靠性。\", \"disclaimer\": \"参考模板，不代表真实招聘，不计入市场热度与岗位证据。\", \"responsibilities\": [\"搭建并优化针对谐波减速器关键零件（如柔轮、刚轮、波发生器）的视觉检测系统，实现表面缺陷、尺寸偏差的自动识别与分类。\", \"制定与迭代视觉检测方案，包括光源、镜头、相机选型及算法参数调优，提升对微小形变与加工纹理的区分能力。\", \"对接生产节拍，将视觉检测工站嵌入谐波减速器装配线，处理检测数据的实时反馈与NG品分流逻辑。\", \"编制检测工艺标准与操作规范，协同工艺与质量部门分析典型失效模式，驱动制程改进。\"], \"technology_node_ids\": [4661, 4703]}','mechanical',NULL,0,'approved','2026-08-28 15:21:33','algorithm_inference');
