CREATE TABLE `biz_review_task` (
  `review_task_id` bigint NOT NULL AUTO_INCREMENT,
  `task_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `queue_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_type_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_id` bigint NOT NULL,
  `priority_score` decimal(7,2) NOT NULL,
  `task_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `assigned_user_id` bigint DEFAULT NULL,
  `target_snapshot_json` json NOT NULL,
  `reason_json` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `updated_at` datetime NOT NULL DEFAULT (now()),
  PRIMARY KEY (`review_task_id`),
  UNIQUE KEY `uk_review_target` (`queue_code`,`target_type_code`,`target_id`),
  UNIQUE KEY `uq_biz_review_task_task_code` (`task_code`),
