  `event_year` int NOT NULL,
  `description_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `maturity_delta_score` decimal(5,2) DEFAULT NULL,
  `verification_status_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `verified_by_user_id` bigint DEFAULT NULL,
