  PRIMARY KEY (`milestone_event_id`),
  UNIQUE KEY `uq_biz_milestone_event_extracted_fact_id` (`extracted_fact_id`),
  UNIQUE KEY `uq_biz_milestone_event_milestone_code` (`milestone_code`),
